-- Data-free function definitions copied from verified Staging catalog exports dated 2026-11-09.
-- SQL semicolons are appended because pg_get_functiondef exports function statements without them.
CREATE OR REPLACE FUNCTION public.is_mq20_profile(p_user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.profiles profile
        WHERE profile.id = p_user_id
          AND UPPER(BTRIM(COALESCE(profile.employee_id, ''))) = 'MQ-20'
          AND profile.is_active IS DISTINCT FROM false
    );
$function$;

CREATE OR REPLACE FUNCTION public.enforce_mq20_task_service_boundaries()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  caller_id uuid := auth.uid();
BEGIN
  IF caller_id IS NULL OR NOT public.is_mq20_profile(caller_id) THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'tasks' THEN
    IF TG_OP = 'INSERT'
       AND NEW.created_by = caller_id
       AND NEW.assignee_id = caller_id
       AND caller_id = ANY(COALESCE(NEW.assignee_ids, '{}'::uuid[]))
       AND NEW.crm_workflow_kind = 'CONTACT_DISCUSSION'
       AND EXISTS (
         SELECT 1 FROM public.crm_generated_tasks generated
         WHERE generated.task_id = NEW.id
           AND generated.deal_id = NEW.crm_deal_id
           AND generated.kind = 'CONTACT_DISCUSSION'
       ) THEN
      RETURN NEW;
    END IF;
  END IF;

  RAISE EXCEPTION 'MQ-20 task access is view-only' USING ERRCODE = '42501';
END;
$function$;

CREATE OR REPLACE FUNCTION public.protect_crm_generated_task_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Preserve the existing privileged deal-deletion path: its FK may detach
    -- surviving tasks, but clients cannot detach a task from an existing deal.
    IF NEW.crm_deal_id IS NULL AND OLD.crm_deal_id IS NOT NULL
       AND NEW.crm_workflow_kind IS NOT DISTINCT FROM OLD.crm_workflow_kind
       AND NOT EXISTS (SELECT 1 FROM public.crm_deals WHERE id = OLD.crm_deal_id) THEN
      RETURN NEW;
    END IF;
    IF NEW.crm_deal_id IS DISTINCT FROM OLD.crm_deal_id
       OR NEW.crm_workflow_kind IS DISTINCT FROM OLD.crm_workflow_kind THEN
      RAISE EXCEPTION 'CRM task identity cannot be changed' USING ERRCODE = '42501';
    END IF;
    IF NEW.crm_workflow_kind IN ('CONTACT_DISCUSSION', 'QUOTE_PROPOSAL_DESIGN')
       AND NEW.status IS DISTINCT FROM OLD.status
       AND LOWER(BTRIM(NEW.status)) IN ('pending approval', 'approved', 'rejected') THEN
      RAISE EXCEPTION 'CRM task approval states are retired' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.crm_deal_id IS NOT NULL OR NEW.crm_workflow_kind IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.crm_generated_tasks
      WHERE task_id = NEW.id AND deal_id = NEW.crm_deal_id AND kind = NEW.crm_workflow_kind) THEN
      RAISE EXCEPTION 'CRM tasks must be generated by the CRM workflow' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.protect_task_access_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF auth.uid() IS NULL OR public.is_task_admin(auth.uid()) THEN RETURN NEW; END IF;
    IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
        RAISE EXCEPTION 'The task creator cannot be changed' USING ERRCODE = '42501';
    END IF;
    IF auth.uid() <> OLD.created_by AND (
        NEW.assignee_id IS DISTINCT FROM OLD.assignee_id
        OR NEW.supervisor_id IS DISTINCT FROM OLD.supervisor_id
        OR NEW.project_id IS DISTINCT FROM OLD.project_id
        OR NEW.parent_task_id IS DISTINCT FROM OLD.parent_task_id
        OR NEW.visibility IS DISTINCT FROM OLD.visibility
        OR NEW.visible_to IS DISTINCT FROM OLD.visible_to
        OR NEW.watchers IS DISTINCT FROM OLD.watchers
    ) THEN
        RAISE EXCEPTION 'Only the task creator can change task access' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$function$;
